sys_script_include.script:
var getEmpDet = Class.create();
getEmpDet.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getEmpInfo: function() {
        var empNum = this.getParameter('sysparm_empnum');
        var result = {};
		gs.info(empNum);
        var empGR = new GlideRecord('x_1216348_claim_0_employee_table');
        empGR.addQuery('sys_id', empNum);
        //empGR.addQuery('sys_id','a6b4ae0a83ee2e10d33033d6feaad3e0');
        empGR.query();
       // gs.info('Get Employee details');

        if (empGR.next()) {
            gs.info('Inside if');
            result.full_name = empGR.full_name+'';
            result.email = empGR.email+'';
			result.contact_no = empGR.contact_no+'';
			//result.document_date = empGR.document_date+'';
			result.account_name = empGR.account_name+'';
			result.account_number = empGR.account_number+'';
			result.bank_name = empGR.bank_name+'';
			result.ifsc_code = empGR.ifsc_code+'';

           // gs.info('fetched details' + result.full_name + result.email);
        }

        return JSON.stringify(result);
    },


    type: 'getEmpDet'
});
